    ...source,
    viewBox: sanitized.viewBox,
    warnings: [...sanitized.warnings, ...idWarnings],
    cleanSvg: serializeSvgRoot(sanitized.root),
    symbolContent: serializeSvgChildren(sanitized.root),
  };
