@'
:root {
  color: #e5edf8;
  background: #0b1020;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  --bg: #0b1020;
  --bg-soft: #10172a;
  --panel: rgba(18, 27, 47, 0.94);
  --panel-solid: #121b2f;
  --panel-raised: #17223a;
  --line: rgba(148, 163, 184, 0.17);
  --line-strong: rgba(148, 163, 184, 0.3);
  --text: #edf4ff;
  --muted: #91a0b8;
  --faint: #68758b;
  --primary: #73e0c1;
  --primary-strong: #3cc7a2;
  --primary-ink: #06231c;
  --secondary: #8ea9ff;
  --warning: #f7bd62;
  --danger: #ff7c86;
  --radius: 16px;
  --radius-sm: 10px;
  --shadow: 0 22px 60px rgba(0, 0, 0, 0.25);
}

* {
  box-sizing: border-box;
}

html {
  min-width: 320px;
  background: var(--bg);
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background:
    radial-gradient(circle at 14% -8%, rgba(115, 224, 193, 0.14), transparent 30%),
    radial-gradient(circle at 92% 6%, rgba(142, 169, 255, 0.13), transparent 34%),
    linear-gradient(180deg, #0c1224 0%, #090e1c 100%);
}

button,
input,
select {
  font: inherit;
}

button {
  color: inherit;
}

button:focus-visible,
input:focus-visible,
select:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}

button:disabled {
  cursor: not-allowed;
  opacity: 0.42;
}

::selection {
  color: #06231c;
  background: var(--primary);
}

::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  border: 3px solid transparent;
  border-radius: 99px;
  background: rgba(148, 163, 184, 0.28);
  background-clip: padding-box;
}

.app-shell {
  min-height: 100vh;
}

.app-header {
  position: sticky;
  z-index: 20;
  top: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  min-height: 76px;
  padding: 14px 24px;
  border-bottom: 1px solid var(--line);
  background: rgba(8, 13, 27, 0.86);
  backdrop-filter: blur(18px);
}

.brand-lockup,
.header-meta,
.panel-heading,
.list-toolbar,
.preview-toolbar,
.inline-control,
.output-heading,
.issue-heading,
.source-tabs {
  display: flex;
  align-items: center;
}

.brand-lockup {
  gap: 13px;
}

.brand-mark {
  position: relative;
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border: 1px solid rgba(115, 224, 193, 0.35);
  border-radius: 13px;
  background: linear-gradient(145deg, rgba(115, 224, 193, 0.2), rgba(142, 169, 255, 0.1));
  box-shadow: inset 0 1px rgba(255, 255, 255, 0.08);
}

.brand-mark span {
  position: absolute;
  width: 17px;
  height: 17px;
  border: 2px solid var(--primary);
  border-radius: 5px;
  transform: rotate(45deg);
}

.brand-mark span:nth-child(2) {
  width: 9px;
  height: 9px;
  border-color: #86a6ff;
}

.brand-mark span:nth-child(3) {
  width: 3px;
  height: 3px;
  border: 0;
  border-radius: 50%;
  background: #fff;
}

.eyebrow,
.section-label {
  display: block;
  color: var(--primary);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

h1,
h2,
p {
  margin: 0;
}

h1 {
  margin-top: 2px;
  font-size: 18px;
  font-weight: 750;
  letter-spacing: -0.02em;
}

h2 {
  margin-top: 4px;
  font-size: 17px;
  font-weight: 700;
  letter-spacing: -0.015em;
}

.header-meta {
  gap: 14px;
  color: var(--muted);
  font-size: 12px;
}

.header-meta > span + span {
  padding-left: 14px;
  border-left: 1px solid var(--line);
}

.offline-pill {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 7px 10px;
  border: 1px solid rgba(115, 224, 193, 0.2);
  border-radius: 999px;
  color: #bdf6e6;
  background: rgba(115, 224, 193, 0.08);
}

.offline-pill i,
.status-dot {
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--primary);
  box-shadow: 0 0 0 4px rgba(115, 224, 193, 0.1);
}

.global-banner {
  display: flex;
  align-items: center;
  gap: 14px;
  margin: 14px 24px 0;
  padding: 11px 14px;
  border: 1px solid rgba(247, 189, 98, 0.25);
  border-radius: 12px;
  color: #f7d69e;
  background: rgba(247, 189, 98, 0.08);
  font-size: 12px;
}

.global-banner span {
  color: #bba980;
}

.workspace {
  display: grid;
  grid-template-columns: minmax(280px, 320px) minmax(460px, 1fr) minmax(310px, 360px);
  align-items: start;
  gap: 16px;
  padding: 16px 24px 32px;
}

.sidebar {
  display: grid;
  gap: 16px;
  min-width: 0;
}

.panel {
  min-width: 0;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--panel);
  box-shadow: var(--shadow);
  backdrop-filter: blur(14px);
}

.import-panel,
.icon-list-panel,
.export-panel {
  padding: 16px;
}

.panel-heading {
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}

.count-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 28px;
  height: 25px;
  padding: 0 8px;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: #c6d2e4;
  background: rgba(255, 255, 255, 0.035);
  font-size: 11px;
  font-weight: 750;
}

.danger-badge,
.warning-badge {
  color: #0d1524;
  border-color: transparent;
}

.danger-badge {
  background: var(--danger);
}

.warning-badge {
  background: var(--warning);
}

.drop-zone {
  position: relative;
  display: grid;
  justify-items: center;
  gap: 8px;
  padding: 22px 14px 16px;
  border: 1px dashed rgba(115, 224, 193, 0.45);
  border-radius: 14px;
  text-align: center;
  background:
    linear-gradient(180deg, rgba(115, 224, 193, 0.065), rgba(115, 224, 193, 0.018)),
    rgba(8, 14, 27, 0.5);
  transition: 180ms ease;
}

.drop-zone.is-dragging {
  border-color: var(--primary);
  background: rgba(115, 224, 193, 0.13);
  transform: translateY(-1px);
}

.drop-zone.is-loading {
  pointer-events: none;
}

.drop-zone-icon {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border: 1px solid rgba(115, 224, 193, 0.35);
  border-radius: 12px;
  color: var(--primary);
  background: rgba(115, 224, 193, 0.1);
  font-size: 25px;
  font-weight: 300;
  line-height: 1;
}

.drop-zone-copy {
  display: grid;
  gap: 3px;
}

.drop-zone-copy strong {
  color: var(--text);
  font-size: 13px;
}

.drop-zone-copy span,
.drop-zone small {
  color: var(--muted);
  font-size: 11px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 38px;
  padding: 0 13px;
  border: 1px solid transparent;
  border-radius: 10px;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: 160ms ease;
}

.button:hover:not(:disabled) {
  transform: translateY(-1px);
}

.button-primary {
  color: var(--primary-ink);
  background: linear-gradient(135deg, #86ebd1, #5fd7b8);
  box-shadow: 0 8px 22px rgba(61, 199, 162, 0.18);
}

.button-secondary {
  color: #dce7f7;
  border-color: var(--line-strong);
  background: rgba(255, 255, 255, 0.055);
}

.button-secondary:hover:not(:disabled),
.button-ghost:hover:not(:disabled) {
  border-color: rgba(115, 224, 193, 0.4);
  background: rgba(115, 224, 193, 0.08);
}

.button-ghost {
  color: var(--muted);
  border-color: var(--line);
  background: transparent;
}

.button-small {
  min-height: 32px;
  padding: 0 10px;
  font-size: 11px;
}

.button-wide {
  width: 100%;
}

.button-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.list-toolbar {
  gap: 8px;
}

.search-field {
  position: relative;
  display: flex;
  align-items: center;
  min-width: 0;
  flex: 1;
}

.search-field input,
.field-input {
  width: 100%;
  height: 38px;
  border: 1px solid var(--line);
  border-radius: 10px;
  color: var(--text);
  background: rgba(7, 12, 24, 0.62);
  transition: 160ms ease;
}

.search-field input {
  padding: 0 10px 0 34px;
}

.search-field input::placeholder,
.field-input::placeholder {
  color: #66738a;
}

.search-field input:focus,
.field-input:focus {
  border-color: rgba(115, 224, 193, 0.55);
  background: rgba(7, 12, 24, 0.86);
}

.search-icon {
  position: absolute;
  z-index: 1;
  left: 11px;
  color: var(--faint);
  font-size: 18px;
  pointer-events: none;
}

.list-meta {
  display: flex;
  justify-content: space-between;
  margin: 12px 2px 8px;
  color: var(--muted);
  font-size: 11px;
}

.warning-text {
  color: var(--warning) !important;
}

.error-text {
  color: var(--danger) !important;
}

.muted-text {
  color: var(--muted);
}

.icon-list {
  display: grid;
  max-height: min(50vh, 570px);
  gap: 8px;
  overflow: auto;
  padding-right: 3px;
}

.icon-list-item {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr) 28px;
  align-items: start;
  gap: 8px;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.025);
  transition: 160ms ease;
}

.icon-list-item:hover {
  border-color: rgba(115, 224, 193, 0.28);
  background: rgba(115, 224, 193, 0.045);
}

.icon-list-index {
  padding-top: 21px;
  color: #617089;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 10px;
}

.icon-list-main {
  min-width: 0;
}

.field-label {
  display: block;
  margin-bottom: 5px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.04em;
}

.rename-input {
  height: 33px;
  padding: 0 9px;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 12px;
}

.list-file-name {
  overflow: hidden;
  margin-top: 5px;
  color: var(--muted);
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.list-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin-top: 6px;
}

.list-tags span {
  padding: 3px 5px;
  border-radius: 5px;
  color: #8190a6;
  background: rgba(255, 255, 255, 0.045);
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 9px;
}

.list-tags .tag-warning {
  color: #f5cf8d;
  background: rgba(247, 189, 98, 0.1);
}

.icon-button {
  display: grid;
  width: 28px;
  height: 28px;
  place-items: center;
  border: 1px solid transparent;
  border-radius: 8px;
  color: var(--muted);
  background: transparent;
  font-size: 20px;
  cursor: pointer;
  transition: 160ms ease;
}

.danger-hover:hover {
  color: #ffd9dc;
  border-color: rgba(255, 124, 134, 0.3);
  background: rgba(255, 124, 134, 0.1);
}

.preview-panel {
  position: sticky;
  top: 92px;
  display: flex;
  flex-direction: column;
  min-height: calc(100vh - 112px);
  max-height: calc(100vh - 92px);
  padding: 16px;
  overflow: hidden;
}

.preview-heading {
  flex: 0 0 auto;
}

.preview-toolbar {
  flex: 0 0 auto;
  flex-wrap: wrap;
  gap: 9px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--line);
}

.preview-search {
  flex: 1 1 180px;
}

.zoom-control {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  font-size: 11px;
}

.zoom-control input {
  width: 92px;
  accent-color: var(--primary);
}

.zoom-value {
  width: 38px;
  color: #b9c5d7;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 10px;
}

.segmented-control {
  display: flex;
  padding: 3px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: rgba(7, 12, 24, 0.5);
}

.segmented-control button {
  height: 27px;
  padding: 0 9px;
  border: 0;
  border-radius: 7px;
  color: var(--muted);
  background: transparent;
  font-size: 10px;
  font-weight: 700;
  cursor: pointer;
}

.segmented-control button.is-active {
  color: #e9f1ff;
  background: rgba(142, 169, 255, 0.18);
}

.toggle-control {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--muted);
  font-size: 10px;
  cursor: pointer;
}

.toggle-control input,
.toggle-switch input {
  accent-color: var(--primary);
}

.preview-grid {
  --preview-size: 112px;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(var(--preview-size), 1fr));
  align-content: start;
  gap: 11px;
  min-height: 0;
  overflow: auto;
  padding: 14px 4px 6px 0;
}

.preview-card {
  position: relative;
  min-width: 0;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: rgba(7, 12, 24, 0.35);
}

.preview-card:hover {
  border-color: rgba(115, 224, 193, 0.32);
}

.preview-canvas {
  display: grid;
  min-height: var(--preview-size);
  place-items: center;
  padding: 14px;
  transition: background 180ms ease;
}

.preview-light .preview-canvas {
  background:
    linear-gradient(45deg, rgba(15, 23, 42, 0.035) 25%, transparent 25%),
    linear-gradient(-45deg, rgba(15, 23, 42, 0.035) 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, rgba(15, 23, 42, 0.035) 75%),
    linear-gradient(-45deg, transparent 75%, rgba(15, 23, 42, 0.035) 75%),
    #f4f7fb;
  background-position: 0 0, 0 8px, 8px -8px, -8px 0;
  background-size: 16px 16px;
}

.preview-dark .preview-canvas {
  background:
    linear-gradient(45deg, rgba(255, 255, 255, 0.025) 25%, transparent 25%),
    linear-gradient(-45deg, rgba(255, 255, 255, 0.025) 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, rgba(255, 255, 255, 0.025) 75%),
    linear-gradient(-45deg, transparent 75%, rgba(255, 255, 255, 0.025) 75%),
    #121a29;
  background-position: 0 0, 0 8px, 8px -8px, -8px 0;
  background-size: 16px 16px;
}

.preview-canvas img {
  display: block;
  width: min(100%, var(--preview-size));
  height: min(100%, var(--preview-size));
  object-fit: contain;
}

.preview-meta {
  display: grid;
  gap: 3px;
  padding: 8px 10px;
  border-top: 1px solid var(--line);
}

.preview-meta strong {
  overflow: hidden;
  color: #dce7f7;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.preview-meta span {
  color: var(--faint);
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 9px;
}

.preview-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1px;
  border-top: 1px solid var(--line);
  background: var(--line);
}

.preview-actions button {
  height: 28px;
  border: 0;
  color: #8594aa;
  background: #10182a;
  font-size: 9px;
  cursor: pointer;
}

.preview-actions button:hover {
  color: var(--primary);
  background: #142036;
}

.preview-warning-dot {
  position: absolute;
  top: 8px;
  right: 8px;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--warning);
  box-shadow: 0 0 0 3px rgba(247, 189, 98, 0.14);
}

.empty-block {
  display: grid;
  place-items: center;
  align-content: center;
  min-height: 220px;
  gap: 7px;
  padding: 28px;
  color: var(--muted);
  text-align: center;
}

.empty-block strong {
  color: #c8d4e6;
  font-size: 13px;
}

.empty-block span {
  font-size: 11px;
}

.compact-empty {
  min-height: 150px;
}

.preview-empty {
  flex: 1;
  min-height: 320px;
}

.empty-illustration {
  display: grid;
  width: 62px;
  height: 62px;
  place-items: center;
  margin-bottom: 5px;
  border: 1px solid rgba(115, 224, 193, 0.22);
  border-radius: 20px;
  color: var(--primary);
  background: rgba(115, 224, 193, 0.06);
  font-size: 28px;
}

.export-panel {
  display: grid;
  gap: 12px;
}

.export-panel .panel-heading {
  margin-bottom: 0;
}

.option-card,
.symbol-copy-card,
.summary-card,
.output-card,
.issue-card {
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.025);
}

.option-card {
  display: grid;
  gap: 11px;
}

.option-card > div:first-child {
  display: grid;
  gap: 3px;
}

.option-card strong {
  font-size: 12px;
}

.option-card span,
.empty-note {
  color: var(--muted);
  font-size: 10px;
}

.toggle-switch,
.toggle-control {
  cursor: pointer;
}

.toggle-switch {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #b9c5d7;
  font-size: 10px;
}

.toggle-switch input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.toggle-track {
  position: relative;
  width: 34px;
  height: 19px;
  border-radius: 999px;
  background: #2b3549;
  transition: 160ms ease;
}

.toggle-track span {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 13px;
  height: 13px;
  border-radius: 50%;
  background: #8b98ad;
  transition: 160ms ease;
}

.toggle-switch input:checked + .toggle-track {
  background: rgba(115, 224, 193, 0.28);
}

.toggle-switch input:checked + .toggle-track span {
  left: 18px;
  background: var(--primary);
}

.export-actions {
  display: grid;
  gap: 8px;
}

.inline-control {
  gap: 8px;
}

.inline-control .field-input {
  height: 34px;
  padding: 0 8px;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 11px;
}

.inline-control .button {
  flex: 0 0 auto;
}

.summary-card {
  display: grid;
  gap: 10px;
}

.summary-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 5px;
}

.summary-grid > div {
  display: grid;
  gap: 3px;
  min-width: 0;
  padding: 8px 6px;
  border-radius: 8px;
  text-align: center;
  background: rgba(7, 12, 24, 0.42);
}

.summary-grid span {
  overflow: hidden;
  color: var(--faint);
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.summary-grid strong {
  color: #dce7f7;
  font-size: 14px;
}

.output-card {
  display: grid;
  gap: 8px;
}

.output-heading,
.issue-heading {
  justify-content: space-between;
}

.output-heading > span:last-child {
  color: var(--muted);
  font-size: 9px;
}

.code-preview {
  max-height: 150px;
  margin: 0;
  overflow: auto;
  padding: 10px;
  border: 1px solid rgba(148, 163, 184, 0.11);
  border-radius: 8px;
  color: #9eb6d4;
  background: rgba(4, 8, 16, 0.66);
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 9px;
  line-height: 1.55;
  white-space: pre-wrap;
  word-break: break-all;
}

.issue-card {
  display: grid;
  gap: 9px;
}

.issue-list {
  display: grid;
  max-height: 170px;
  gap: 6px;
  overflow: auto;
}

.issue-item {
  display: grid;
  gap: 3px;
  padding: 8px;
  border-left: 2px solid var(--line-strong);
